import { db, getMeta } from '@/db/schema.js';
import { loadSettings } from '@/db/repo.js';
import { isDesktopShell, isNativeShell } from '@/lib/platform/detect.js';
import { platform } from '@/lib/platform/index.js';

/**
 * Practice days after which a summary is no longer the first one. One: the
 * offer belongs to the day somebody first practised, when coming back
 * tomorrow is the thing that matters most.
 */
export const FIRST_PRACTICE_DAYS = 1;

/** The reminder time the offer names: the hour this session happened in, so it rings when they practise. */
export function reminderHour(now: Date = new Date()): string {
  return `${String(now.getHours()).padStart(2, '0')}:00`;
}

/**
 * Whether this device rings the daily reminder itself: the phone apps, and
 * the desktop app, whose core hands the plan to macOS or Windows
 * (`schedule_reminders`). A browser tab cannot, and has its own offer
 * (`features/reminder/webOffer.ts`). Until 24 Oct 2026 the desktop app was
 * asked only in the introduction, which an account signed in from the
 * browser never sees, and none of its accounts had a reminder.
 */
export function remindsHere(): boolean {
  return isNativeShell() || isDesktopShell();
}

/**
 * Whether a reminder turned on here would show. Only the desktop app can say
 * no without asking anybody: notifications switched off under Settings, This
 * computer, are the learner's own answer, so nothing offers to turn the
 * reminder on over it. When the core cannot be read, nothing is offered
 * either. Everywhere else the system's own permission prompt decides.
 */
export async function notificationsAllowedHere(): Promise<boolean> {
  if (!isDesktopShell()) return true;
  const desktop = platform.desktop;
  if (desktop === undefined) return false;
  try {
    return (await desktop.settings.read()).notifications;
  } catch {
    return false;
  }
}

/**
 * Whether this summary offers the daily reminder: only where this device
 * can deliver it (`remindsHere`); only with no reminder set and none
 * declined on Today; only on the first day with practice; and only once on
 * this device, ever.
 */
export async function shouldOfferReminder(): Promise<boolean> {
  if (!remindsHere()) return false;
  const [asked, dismissed, settings] = await Promise.all([
    getMeta('reminderAsked'),
    getMeta('reminderOfferDismissed'),
    loadSettings(),
  ]);
  if (asked || dismissed || (settings?.reminderTime ?? '') !== '') return false;
  if (!(await notificationsAllowedHere())) return false;
  const days = await db.dayStats.filter((stat) => stat.reviewed > 0).count();
  return days <= FIRST_PRACTICE_DAYS;
}
